import{_ as t,c as s,o as r,j as e,a as o}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"原序","description":"周易口诀义 - 原序","frontmatter":{"title":"原序","description":"周易口诀义 - 原序"},"headers":[],"relativePath":"zh/classics/koujueyi/002.md","filePath":"zh/classics/koujueyi/002.md"}'),i={name:"zh/classics/koujueyi/002.md"};function c(n,a,l,d,p,u){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"原序",tabindex:"-1"},[o("原序 "),e("a",{class:"header-anchor",href:"#原序","aria-label":"Permalink to “原序”"},"​")],-1),e("p",null,"乾象既分，苍牙应运，三才阐位，八卦昭彰。故能道济不通，人用无极。自兹已降，祖述多家。田何传于丁宽，京房得之焦贡。遂使异闻竞起，蹖駮纷多，深乖述作之由，全误圣人之见。若使广求文句，博引证验，浮诞日兴，华伪滋蔓。诚谓周鼠终亏于郑璞，鱼目以混于随珠。今则但举宏机，纂其枢要。先以王注为宗，后约孔疏为理。至于卦繇六位，并备而释之；彖以详略，阙而不叙。大抵举其六卷，分为上、下两经，直以口诀为名，义决要为旨。或经象未显，辄提纬以证文；传疏未明，将考名以销义。遂使疑祛理悟，还希述作之功；学寡难周，耻腾波于翰海云尔。",-1)])])}const f=t(i,[["render",c]]);export{_ as __pageData,f as default};
